694: advance_last_committed_txid(BCDBShmXact *tx)
695: {
696: 	const bool collect_gate_stats = unlikely(bcdb_gate_telemetry_enabled);
697: 	BCBlock *blk   = get_block1_cached(true);
698: 	int      slots = bcdb_get_runtime_result_ring_slots();
699: 	BCTxID   my_id = tx->tx_id;
700: 	BCTxID   prev  = my_id - 1;
701: 	BCTxID   cur;
702: 	bool     watermark_advanced = false;
703: 
704:     if (slots < 1)
705:         slots = 1;
706: 
707: 	if (collect_gate_stats)
708: 		SHARD_INC(commit_advance_calls);
709: 
710: 	/*
711: 	 * Step 1: Try to claim "I am the next to commit". CAS succeeds iff our
712: 	 * immediate predecessor has already published; otherwise bail and let
713: 	 * the predecessor's eventual scan pick up our slot.
714: 	 */
715: 	if (!__sync_bool_compare_and_swap(&blk->last_committed_tx_id, prev, my_id))
716: 	{
717: 		/* Telemetry: CAS lost — predecessor not yet committed. */
718: 		if (collect_gate_stats)
719: 			SHARD_INC(commit_initial_cas_failures);
720: 		return;
721: 	}
722: 
723: 	watermark_advanced = true;
724: 
725: 	/* Step 2: Mirror the watermark on block_meta. Broadcast deferred to end. */
726: 	__atomic_store_n(&block_meta->num_committed, my_id, __ATOMIC_RELEASE);
727: 
728: 	/*
729: 	 * Step 3: Opportunistically carry the watermark forward through any
730: 	 * already-published successor slots. Each iteration:
731: 	 *   - locate the ring slot owned by the next contiguous txid;
732: 	 *   - load it with ACQUIRE so a successful match also synchronises
733: 	 *     with the successor's RELEASE store of its result tuple;
734: 	 *   - CAS our watermark forward (paranoia: another scanner may race).
735: 	 *
736: 	 * CORRECTNESS FIX: the broadcast is intentionally deferred until AFTER
737: 	 * the full prefix scan (Step 4).  Broadcasting only after the initial CAS
738: 	 * created a race: a waiter could wake, observe its target not yet reached,
739: 	 * go back to sleep, and then miss the final watermark advance that happens
740: 	 * within this very loop.  A single broadcast at the end of the scan covers
741: 	 * all advances atomically from the waiter's perspective.
742: 	 */
743: 	cur = my_id;
744: 	int advanced_steps = 0;
745: 	for (int step = 0; step < slots; step++)
746: 	{
747: 		BCTxID next_id   = cur + 1;
748: 		int    next_slot = (int)(next_id % (BCTxID)slots);
749: 		BCTxID published;
750: 
751: 		if (next_slot < 0)
752: 			next_slot += slots;
753: 
754: 		published = __atomic_load_n(&blk->result_committed_txid[next_slot],
755: 									__ATOMIC_ACQUIRE);
756: 		if (published != next_id)
757: 			break;              	/* gap: successor not yet ready */
758: 		if (!__sync_bool_compare_and_swap(&blk->last_committed_tx_id, cur, next_id))
759: 			break;              	/* another scanner advanced past us */
760: 
761: 		__atomic_store_n(&block_meta->num_committed, next_id, __ATOMIC_RELEASE);
762: 		if (collect_gate_stats)
763: 			advanced_steps++;
764: 		cur = next_id;
765: 	}
766: 
767: 	if (collect_gate_stats && advanced_steps > 0)
768: 	{
769: 		for (int i = 0; i < advanced_steps; i++)
770: 			SHARD_INC(commit_prefix_steps);
771: 	}
772: 
773: 	/*
774: 	 * Step 4: Single broadcast AFTER the full contiguous prefix has been
775: 	 * advanced.  Any waiter in bcdb_wait_until_committed() or
776: 	 * bcdb_wait_for_prev_committed() that parked on condCommit will now
777: 	 * re-check the watermark and observe the final value.
778: 	 */
779: 	if (watermark_advanced &&
780: 		bcdb_serial_gate_mode == BCDB_SERIAL_GATE_MODE_CONDVAR)

