4201: bcdb_dt_validate_published(BCTxID published, bool at_turn)
4202: {
4203: 	BCTxID first;
4204: 
4205: 	if (!bcdb_dt_conflict_tracking)
4206: 		return 0;
4207: 	/*
4208: 	 * Only predecessors can conflict.  published_max can already be past our
4209: 	 * own id when this transaction re-runs after its first publication (the
4210: 	 * historical post-publish restart); scanning our own digest would then
4211: 	 * report a conflict with ourselves and wait for our own commit forever.
4212: 	 */
4213: 	if (published >= activeTx->tx_id)
4214: 		published = activeTx->tx_id - 1;
4215: 	if (!bcdb_dt_validation_started && !at_turn)
4216: 		goto full_check;
4217: 	bcdb_reset_last_conflict_txid();
4218: 	first = Max(bcdb_dt_validated_through, activeTx->tx_id_committed) + 1;
4219: 	if ((int64) published - first >= BCDB_DT_DIGEST_SLOTS)
4220: 		goto fallback;
4221: 	for (BCTxID id = first; id <= published; id++)
4222: 	{
4223: 		BCDBDTDigest *digest = &bcdb_dt_digests[id % BCDB_DT_DIGEST_SLOTS];
4224: 		uint32 count;
4225: 		bool hit = false;
4226: 
4227: 		if (__atomic_load_n(&digest->tx_id, __ATOMIC_ACQUIRE) != id)
4228: 			goto fallback;
4229: 		count = __atomic_load_n(&digest->count, __ATOMIC_RELAXED);
4230: 		if (count > BCDB_DT_DIGEST_TAGS)
4231: 			goto fallback;
4232: 		for (uint32 i = 0; i < count; i++)
4233: 		{
4234: 			if (bcdb_dt_digest_intersects(__atomic_load_n(&digest->hashes[i], __ATOMIC_RELAXED)))
4235: 			{
4236: 				hit = true;
4237: 				break;
4238: 			}
4239: 		}
4240: 		pg_read_barrier();
4241: 		if (__atomic_load_n(&digest->tx_id, __ATOMIC_ACQUIRE) != id)
4242: 			goto fallback;
4243: 		bcdb_ptrace_inc_counter(BCDB_PTRACE_COUNTER_INCREMENTAL_TXS_CHECKED, 1);
4244: 		if (hit)
4245: 		{
4246: 			bcdb_last_conflict_txid = id;
4247: 			return 1;
4248: 		}
4249: 	}
4250: 	bcdb_dt_validation_started = true;
4251: 	bcdb_dt_validated_through = Max(bcdb_dt_validated_through, published);
4252: 	return 0;
4253: 
4254: fallback:
4255: 	bcdb_ptrace_inc_counter(BCDB_PTRACE_COUNTER_RING_FALLBACKS, 1);
4256: full_check:
4257: 	if (conflict_checkDT())
4258: 		return 1;
4259: 	bcdb_dt_validation_started = true;
4260: 	bcdb_dt_validated_through = Max(bcdb_dt_validated_through, published);
4261: 	return 0;
4262: }
