4264: /*
4265:  * conflict_check  (non-DT path)
4266:  *
4267:  * Legacy conflict check used when OEP_mode=false or the Deterministic
4268:  * Execution (DT) scheme is not active.  Walks ws_table_record and
4269:  * rs_table_record using ws_table_check() / rs_table_check() against
4270:  * ws_table->map.
4271:  *
4272:  * Design note: because ws_table_reserve() (which populated ws_table->map)
4273:  * has been removed, ws_table_check() and rs_table_check() always return
4274:  * false.  This function is therefore a no-op for conflict detection in the
4275:  * current codebase.  It is kept to avoid breaking the non-DT code path
4276:  * in worker.c.  If the non-DT path needs to be made functional again,
4277:  * ws_table_reserve() and rs_table_reserve() should be re-introduced.
4278:  */
4279: void conflict_check(void)
4280: {
4281:     WSTableEntryRecord *record;
4282: 
4283:     LIST_FOREACH(record, &ws_table_record, link)
4284:     {
4285:         if (ws_table_check(&record->tag))
